#!/usr/bin/env python3
"""Check scoped lock identities, features and unchanged runtime source bindings."""

from pathlib import Path
import hashlib
import json
import os
import re
import subprocess
import tomllib

SCRIPT_HOME = Path(__file__).resolve().parent
HERE = Path(os.environ.get('FSYM_VALIDATION_OUTPUT', str(SCRIPT_HOME))).resolve()
SCOPE = json.loads((HERE / 'scope.json').read_text())
SOURCE = Path(SCOPE['source_root'])
BASE = '3e35c727e6b2a6024fce55d80e20ee980dd5a6bb'


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    key = lambda row: (row['name'], row['version'], row.get('source'))
    production = {
        key(row): row for row in tomllib.loads((SOURCE / 'Cargo.lock').read_text())['package']
    }
    scoped = tomllib.loads((HERE / 'Cargo.lock').read_text())['package']
    external = [row for row in scoped if 'source' in row]
    for row in external:
        assert key(row) in production, key(row)
        assert row.get('checksum') == production[key(row)].get('checksum'), key(row)
    metadata = json.loads((HERE / 'metadata.json').read_text())
    packages = {p['id']: p for p in metadata['packages']}
    expected_features = {}
    for line in Path(SCOPE.get('production_tree', str(SCRIPT_HOME / 'production-tree.txt'))).read_text().splitlines():
        match = re.fullmatch(
            r'([^ ]+) v([^ ]+)(?: \([^)]*\))* \[([^\]]*)\](?: \(\*\))?', line
        )
        assert match, line
        expected_features[(match[1], match[2])] = sorted(filter(None, match[3].split(',')))
    checked = []
    for node in metadata['resolve']['nodes']:
        package = packages[node['id']]
        if package['name'] in ('frankensympy-session-validation', 'fsym-runtime-session-validation'):
            continue
        identity = (package['name'], package['version'])
        assert expected_features[identity] == sorted(node['features']), {
            'package': identity, 'production': expected_features[identity], 'scope': node['features']
        }
        checked.append({'name': identity[0], 'version': identity[1], 'features': node['features']})
    sources = []
    for package in metadata['packages']:
        if package['source'] is not None:
            continue
        manifest = Path(package['manifest_path'])
        if not manifest.is_relative_to(SOURCE):
            continue
        for path in [manifest, *sorted((manifest.parent / 'src').rglob('*.rs'))]:
            sources.append({'path': str(path.relative_to(SOURCE)), 'sha256': sha(path)})
    for name in ('workspace', 'protocol', 'publication', 'fmap', 'replay'):
        relative = f'crates/fsym-runtime/src/{name}.rs'
        path = SOURCE / relative
        expected = subprocess.check_output(['git', 'show', f'{BASE}:{relative}'], cwd=SOURCE)
        assert path.read_bytes() == expected, relative
        sources.append({'path': relative, 'sha256': sha(path)})
    result = {
        'base': BASE, 'external_identities_verified': len(external),
        'retained_feature_sets_verified': checked,
        'production_lock_sha256': sha(SOURCE / 'Cargo.lock'),
        'validation_lock_sha256': sha(HERE / 'Cargo.lock'),
        'lower_source_snapshot': sources,
        'harness_files': {
            str(path.relative_to(HERE)): sha(path)
            for path in [HERE / 'Cargo.toml', HERE / 'runtime/Cargo.toml', HERE / 'runtime/lib.rs',
                         HERE / 'feature-unification.rs']
        },
        'preparation_scripts': {str(path): sha(path) for path in [SCRIPT_HOME / 'prepare_scope.py', Path(__file__)]},
        'scope': 'Selected actual root and mathematical source plus five unchanged production synchronous runtime modules.',
        'full_runtime_workspace_gate': False,
    }
    (HERE / 'verification.json').write_text(json.dumps(result, indent=2) + '\n')
    print(json.dumps({'external_identities_verified': len(external),
                      'retained_feature_sets_verified': len(checked),
                      'lower_sources': len(sources), 'manifest': str(HERE / 'verification.json')}))


if __name__ == '__main__':
    main()
